import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"বেশি পরিশ্রম বেশি পুরস্কারের বণ্টন নীতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/06-多劳多得分配原理.md","filePath":"bn/06-多劳多得分配原理.md","lastUpdated":null}'),o={name:"bn/06-多劳多得分配原理.md"};function d(i,t,h,n,u,s){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="বেশি-পরিশ্রম-বেশি-পুরস্কারের-বণ্টন-নীতি" tabindex="-1">বেশি পরিশ্রম বেশি পুরস্কারের বণ্টন নীতি <a class="header-anchor" href="#বেশি-পরিশ্রম-বেশি-পুরস্কারের-বণ্টন-নীতি" aria-label="Permalink to &quot;বেশি পরিশ্রম বেশি পুরস্কারের বণ্টন নীতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>06</td></tr><tr><td>মডিউল</td><td>মূল নীতি ও কোর সেটিং</td></tr><tr><td>মূল কীওয়ার্ড</td><td>বেশি পরিশ্রম বেশি পুরস্কার, বণ্টন, অবদান, উৎপাদন-সংযুক্ত চুক্তি, ন্যায়বিচার ও দক্ষতা</td></tr></tbody></table><h2 id="_1-বেশি-পরিশ্রম-বেশি-পুরস্কারের-মৌলিক-সংজ্ঞা" tabindex="-1">1. বেশি পরিশ্রম বেশি পুরস্কারের মৌলিক সংজ্ঞা <a class="header-anchor" href="#_1-বেশি-পরিশ্রম-বেশি-পুরস্কারের-মৌলিক-সংজ্ঞা" aria-label="Permalink to &quot;1. বেশি পরিশ্রম বেশি পুরস্কারের মৌলিক সংজ্ঞা&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কার হলো নোঙর সহজীবী সভ্যতার মূল বণ্টন নীতি, যার অর্থ হলো সাধনা সম্পদ, বিবর্তনের সুযোগ, সামাজিক সম্মান ইত্যাদি দুষ্প্রাপ্য মূল্যের বণ্টনে, ব্যক্তি বা গোষ্ঠীর সহজীবী জালের প্রতি প্রকৃত অবদানকে প্রধান ভিত্তি হিসেবে গ্রহণ করা। অবদান যত বেশি, বণ্টনের অংশ তত বেশি; অবদান যত কম, বণ্টনের অংশ তত কম। বেশি পরিশ্রম বেশি পুরস্কার অপরিশ্রমী লুণ্ঠনমূলক বণ্টনের বিরোধিতা করে, এবং বেশি-কম পরিশ্রমে একই রকম গড়বাদী বণ্টনেরও বিরোধিতা করে।</p><p>&quot;পরিশ্রম&quot; সহজীবী সভ্যতায় নির্দিষ্ট অন্তর্নিহিত অর্থ রাখে, যা শুধু শারীরিক পরিশ্রমকেই বোঝায় না, বরং সাধনার উন্নতি, জ্ঞান সৃষ্টি, প্রযুক্তিগত উদ্ভাবন, নোঙর বিন্দু রক্ষণাবেক্ষণ, সভ্যতার শাসন, জাতিগত সহযোগিতা ইত্যাদি সহজীবী জালের প্রতি ইতিবাচক অবদান রাখা সব কার্যক্রমকে অন্তর্ভুক্ত করে। &quot;পুরস্কার&quot;ও শুধু বস্তুগত সম্পদকেই বোঝায় না, বরং বিবর্তনের সুযোগ, নোঙর বিন্দু সংযোগ অধিকার, প্রশিক্ষক নির্দেশনার যোগ্যতা, বিমান অন্বেষণের অগ্রাধিকার ইত্যাদি সমন্বিত বিবর্তন সহায়তাকেও অন্তর্ভুক্ত করে।</p><h2 id="_2-বেশি-পরিশ্রম-বেশি-পুরস্কারের-তাত্ত্বিক-ভিত্তি" tabindex="-1">2. বেশি পরিশ্রম বেশি পুরস্কারের তাত্ত্বিক ভিত্তি <a class="header-anchor" href="#_2-বেশি-পরিশ্রম-বেশি-পুরস্কারের-তাত্ত্বিক-ভিত্তি" aria-label="Permalink to &quot;2. বেশি পরিশ্রম বেশি পুরস্কারের তাত্ত্বিক ভিত্তি&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কার নীতির প্রতিষ্ঠা, নিম্নলিখিত ত্রিভুজ তাত্ত্বিক বিবেচনার উপর ভিত্তি করে:</p><h3 id="_2-1-উদ্দীপনা-তত্ত্ব-অবদানের-ইতিবাচক-প্রতিক্রিয়া-প্রয়োজন" tabindex="-1">2.1 উদ্দীপনা তত্ত্ব: অবদানের ইতিবাচক প্রতিক্রিয়া প্রয়োজন <a class="header-anchor" href="#_2-1-উদ্দীপনা-তত্ত্ব-অবদানের-ইতিবাচক-প্রতিক্রিয়া-প্রয়োজন" aria-label="Permalink to &quot;2.1 উদ্দীপনা তত্ত্ব: অবদানের ইতিবাচক প্রতিক্রিয়া প্রয়োজন&quot;">​</a></h3><p>বিবর্তন এমন একটি প্রক্রিয়া যার জন্য ক্রমাগত বিনিয়োগ প্রয়োজন। যদি অবদান ও প্রতিদান বিচ্ছিন্ন হয়ে যায়, ব্যক্তি ক্রমাগত বিনিয়োগের অনুপ্রেরণা হারাবে, এবং সমগ্র সহজীবী জালের বিবর্তন দক্ষতা হ্রাস পাবে। বেশি পরিশ্রম বেশি পুরস্কার অবদান ও প্রতিদানের মধ্যে ইতিবাচক প্রতিক্রিয়ার চক্র স্থাপন করে, প্রতিটি জীবকে তার সম্ভাবনাকে সর্বোচ্চ সীমায় প্রদর্শন করতে উদ্বুদ্ধ করে, এবং সহজীবী জালের জন্য আরও মূল্য সৃষ্টি করে।</p><h3 id="_2-2-ন্যায়বিচার-তত্ত্ব-অবদান-অনুযায়ী-বণ্টন-হলো-সবচেয়ে-মৌলিক-ন্যায়বিচার" tabindex="-1">2.2 ন্যায়বিচার তত্ত্ব: অবদান অনুযায়ী বণ্টন হলো সবচেয়ে মৌলিক ন্যায়বিচার <a class="header-anchor" href="#_2-2-ন্যায়বিচার-তত্ত্ব-অবদান-অনুযায়ী-বণ্টন-হলো-সবচেয়ে-মৌলিক-ন্যায়বিচার" aria-label="Permalink to &quot;2.2 ন্যায়বিচার তত্ত্ব: অবদান অনুযায়ী বণ্টন হলো সবচেয়ে মৌলিক ন্যায়বিচার&quot;">​</a></h3><p>সহজীবী সভ্যতায়, ন্যায়বিচার গড়কে বোঝায় না। প্রকৃত ন্যায়বিচার হলো প্রতিটি জীবের পরিশ্রমের সাথে মেলে এমন প্রতিদান পাওয়া। একজন কঠোর পরিশ্রমের মাধ্যমে উচ্চ স্তরে পৌঁছানো সাধক, আরও সম্পদ ও সুযোগ পাওয়া, এটি তার পরিশ্রমের যুক্তিসঙ্গত প্রতিদান; একজন কোনো পরিশ্রম করতে অনিচ্ছুক ব্যক্তি, শুধু মৌলিক সহায়তা পাওয়া, এটিও ন্যায়বিচারের প্রকাশ। বেশি পরিশ্রম বেশি পুরস্কার যা রক্ষা করে তা হলো পরিশ্রমী ও স্রষ্টাদের অধিকার।</p><h3 id="_2-3-দক্ষতা-তত্ত্ব-সম্পদ-সর্বাধিক-মূল্য-সৃষ্টি-করতে-সকল-স্থানে-প্রবাহিত-হওয়া-উচিত" tabindex="-1">2.3 দক্ষতা তত্ত্ব: সম্পদ সর্বাধিক মূল্য সৃষ্টি করতে সকল স্থানে প্রবাহিত হওয়া উচিত <a class="header-anchor" href="#_2-3-দক্ষতা-তত্ত্ব-সম্পদ-সর্বাধিক-মূল্য-সৃষ্টি-করতে-সকল-স্থানে-প্রবাহিত-হওয়া-উচিত" aria-label="Permalink to &quot;2.3 দক্ষতা তত্ত্ব: সম্পদ সর্বাধিক মূল্য সৃষ্টি করতে সকল স্থানে প্রবাহিত হওয়া উচিত&quot;">​</a></h3><p>মহাবিশ্বের সাধনা সম্পদ প্রযুক্তিগত উপায়ে ক্রমাগত বৃদ্ধি করা যায় তবেও, নির্দিষ্ট স্থান-কালে এগুলো এখনও সীমিত। বেশি পরিশ্রম বেশি পুরস্কার ব্যবস্থা সম্পদকে অগ্রাধিকারমূলকভাবে বেশি অবদান ও বেশি দক্ষতার ব্যক্তি ও গোষ্ঠীর কাছে বণ্টন করে, সীমিত সম্পদ থেকে সর্বোচ্চ বিবর্তন কার্যকারিতা তৈরি করে। এটি দুর্বলদের পরিত্যাগ নয়, বরং সমগ্র বিবর্তন দক্ষতার প্রতি দায়বদ্ধতা — সমগ্র দক্ষতা বৃদ্ধির পর, দুর্বলদের সহায়তার জন্য আরও সম্পদ থাকে।</p><h2 id="_3-অবদানের-পরিমাণমূলক-মূল্যায়ন-ব্যবস্থা" tabindex="-1">3. অবদানের পরিমাণমূলক মূল্যায়ন ব্যবস্থা <a class="header-anchor" href="#_3-অবদানের-পরিমাণমূলক-মূল্যায়ন-ব্যবস্থা" aria-label="Permalink to &quot;3. অবদানের পরিমাণমূলক মূল্যায়ন ব্যবস্থা&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কার নীতিকে কার্যকর করার যোগ্য করার জন্য, সহজীবী সভ্যতা পদ্ধতিগত অবদানের পরিমাণমূলক মূল্যায়ন ব্যবস্থা প্রতিষ্ঠা করেছে:</p><table tabindex="0"><thead><tr><th>অবদানের প্রকার</th><th>মূল্যায়নের মাত্রা</th><th>পরিমাণমূলক পদ্ধতি</th></tr></thead><tbody><tr><td>সাধনা অবদান</td><td>স্তর বৃদ্ধির গতি, স্তরের উচ্চতা, সাধনা সফলতার আদর্শ প্রভাব</td><td>নোঙর বিন্দু জাল স্বয়ংক্রিয়ভাবে সাধনা ডেটা রেকর্ড করে, সাধনা অবদান মানে রূপান্তরিত করে</td></tr><tr><td>জ্ঞান অবদান</td><td>সাধনা অভিজ্ঞতার প্রকাশ্যে ভাগাভাগি, নতুন সাধনা পদ্ধতির সৃষ্টি, তাত্ত্বিক গবেষণার ফলাফল</td><td>একাডেমিক কমিটি দ্বারা পর্যালোচনা, জ্ঞানের প্রভাব ও উদ্ভাবনীতার উপর ভিত্তি করে মান নির্ধারণ</td></tr><tr><td>প্রযুক্তিগত অবদান</td><td>নিয়ম প্রকৌশলের প্রযুক্তিগত উদ্ভাবন, দ্বিগুণ ফলের প্রয়োগের অপ্টিমাইজেশন, নোঙর বিন্দু হার্ডওয়্যারের উন্নতি</td><td>প্রযুক্তিগত কমিটি দ্বারা পর্যালোচনা, প্রযুক্তির ব্যবহারিক মূল্য ও প্রসারের পরিসরের উপর ভিত্তি করে মান নির্ধারণ</td></tr><tr><td>সেবা অবদান</td><td>প্রশিক্ষক নির্দেশনার সময়কাল, নোঙর বিন্দু রক্ষণাবেক্ষণের পরিমাণ, সভ্যতার শাসনে অংশগ্রহণ</td><td>নোঙর বিন্দু জাল স্বয়ংক্রিয়ভাবে সেবার সময়কাল ও মান রেকর্ড করে, সেবা অবদান মানে রূপান্তরিত করে</td></tr><tr><td>পরিবেশগত অবদান</td><td>গ্রহের পরিবেশ পুনরুদ্ধার, বিমানের শক্তি চক্রের উন্নতি, মহাবিশ্বের পরিবেশ সুরক্ষা</td><td>পরিবেশগত কমিটি দ্বারা মূল্যায়ন, পরিবেশগত উন্নতির পরিসর ও স্থায়িত্বের উপর ভিত্তি করে মান নির্ধারণ</td></tr><tr><td>সহযোগিতার অবদান</td><td>জাতি-ব্যাপী সহযোগিতা প্রকল্পে অংশগ্রহণ, হাজারো জাতির প্রজাতন্ত্র বিষয়ে অবদান</td><td>প্রজাতন্ত্র পরিষদ দ্বারা মূল্যায়ন, সহযোগিতার গভীরতা ও ফলাফলের উপর ভিত্তি করে মান নির্ধারণ</td></tr></tbody></table><p>ব্যক্তির মোট অবদান মান হলো বিভিন্ন ধরনের অবদান মানের ওজনযুক্ত সমষ্টি, এবং ওজন সভ্যতার বিকাশের পর্যায়ের প্রয়োজন অনুযায়ী গতিশীলভাবে সামঞ্জস্য করা হয়। অবদান মান প্রতি ত্রৈমাসিকে একবার নিষ্পত্তি করা হয়, এবং পরের ত্রৈমাসিকের সম্পদ বণ্টনের প্রধান ভিত্তি হিসেবে ব্যবহৃত হয়।</p><h2 id="_4-উৎপাদন-সংযুক্ত-চুক্তি-ব্যবস্থা" tabindex="-1">4. উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থা <a class="header-anchor" href="#_4-উৎপাদন-সংযুক্ত-চুক্তি-ব্যবস্থা" aria-label="Permalink to &quot;4. উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থা&quot;">​</a></h2><p>উৎপাদন-সংযুক্ত চুক্তি হলো সাধনা সম্পদ বণ্টনের ক্ষেত্রে বেশি পরিশ্রম বেশি পুরস্কার নীতির নির্দিষ্ট প্রাতিষ্ঠানিক নকশা, এবং এর মূল চিন্তা হলো &quot;গোষ্ঠীতে উৎপাদন বরাদ্দ, উৎপাদনের সাথে যুক্ত পারিশ্রমিক, অতিরিক্ত উৎপাদনের পুরস্কার&quot;।</p><h3 id="_4-1-মৌলিক-কার্যকারিতা-পদ্ধতি" tabindex="-1">4.1 মৌলিক কার্যকারিতা পদ্ধতি <a class="header-anchor" href="#_4-1-মৌলিক-কার্যকারিতা-পদ্ধতি" aria-label="Permalink to &quot;4.1 মৌলিক কার্যকারিতা পদ্ধতি&quot;">​</a></h3><ol><li><strong>সম্পদের চুক্তি</strong>: সহজীবী সভ্যতা একটি নির্দিষ্ট অঞ্চলের সাধনা সম্পদ (যেমন আধ্যাত্মিক শিরা, ঔষধ ক্ষেত্র, শক্তি খনিজ শিরা ইত্যাদি) সাধক গোষ্ঠী বা জাতি সম্প্রদায়ের কাছে চুক্তি দেয়</li><li><strong>উৎপাদনের নির্ধারণ</strong>: সম্পদের মৌলিক উৎপাদন ক্ষমতা ও চুক্তিকারীর ক্ষমতার উপর ভিত্তি করে, যুক্তিসঙ্গত উৎপাদন নির্ধারণ সেট করা হয়</li><li><strong>উৎপাদনের সাথে যুক্ত পারিশ্রমিক</strong>: চুক্তিকারীর প্রাপ্ত সম্পদের অংশ তার প্রকৃত উৎপাদনের সাথে যুক্ত, নির্ধারণ পূরণ করলে মৌলিক অংশ পাওয়া যায়, অতিরিক্ত উৎপাদনের অংশ অনুপাত অনুযায়ী পুরস্কার দেওয়া হয়</li><li><strong>স্বায়ত্তশাসিত পরিচালনা</strong>: চুক্তিকারীর লুণ্ঠন-বিরোধী নীতি ও পরিবেশ সুরক্ষা আইন লঙ্ঘন না করার শর্তে, সম্পদের উন্নয়ন ও ব্যবহারের পদ্ধতি স্বায়ত্তশাসিতভাবে সিদ্ধান্ত নেওয়ার অধিকার রয়েছে</li></ol><h3 id="_4-2-উৎপাদন-সংযুক্ত-চুক্তির-সুবিধা" tabindex="-1">4.2 উৎপাদন-সংযুক্ত চুক্তির সুবিধা <a class="header-anchor" href="#_4-2-উৎপাদন-সংযুক্ত-চুক্তির-সুবিধা" aria-label="Permalink to &quot;4.2 উৎপাদন-সংযুক্ত চুক্তির সুবিধা&quot;">​</a></h3><ul><li>সমষ্টিগত সম্পদের ব্যবহারের দক্ষতাকে চুক্তিকারীর ব্যক্তিগত স্বার্থের সাথে সরাসরি যুক্ত করে, চুক্তিকারীকে সততার সাথে কাজ করতে উদ্বুদ্ধ করে</li><li>সম্পদের গড় বণ্টনের ফলে সৃষ্ট &quot;সাধারণ ভূমির ট্র্যাজেডি&quot; এড়ায়, সম্পদ ব্যবহারের দক্ষতা বাড়ায়</li><li>চুক্তিকারী অতিরিক্ত উৎপাদনের পুরস্কারের উদ্দীপনায়, প্রযুক্তিগত উদ্ভাবন ও পরিচালনার অপ্টিমাইজেশন করতে অনুপ্রাণিত হয়</li><li>সাধকদের জন্য স্থিতিশীল সম্পদ অর্জনের চ্যানেল প্রদান করে, লুণ্ঠন আচরণের আর্থিক উদ্দেশ্য হ্রাস করে</li></ul><h3 id="_4-3-ঝুঁকি-সহায়তা" tabindex="-1">4.3 ঝুঁকি সহায়তা <a class="header-anchor" href="#_4-3-ঝুঁকি-সহায়তা" aria-label="Permalink to &quot;4.3 ঝুঁকি সহায়তা&quot;">​</a></h3><p>উৎপাদন-সংযুক্ত চুক্তি ঝুঁকিকে সম্পূর্ণরূপে চুক্তিকারীর কাছে হস্তান্তর করে না। সহজীবী সভ্যতা &quot;চুক্তি ঝুঁকি সহায়তা তহবিল&quot; স্থাপন করেছে, এবং অপ্রতিরোধ্য প্রাকৃতিক দুর্যোগ, বিমানের ঊর্মি ইত্যাদি পরিস্থিতিতে, চুক্তিকারীকে মৌলিক সহায়তা প্রদান করে, এবং তারা দুর্ঘটনার কারণে মৌলিক সাধনার শর্ত হারাবে না তা নিশ্চিত করে।</p><h2 id="_5-মৌলিক-সহায়তা-ও-বেশি-পরিশ্রম-বেশি-পুরস্কারের-ভারসাম্য" tabindex="-1">5. মৌলিক সহায়তা ও বেশি পরিশ্রম বেশি পুরস্কারের ভারসাম্য <a class="header-anchor" href="#_5-মৌলিক-সহায়তা-ও-বেশি-পরিশ্রম-বেশি-পুরস্কারের-ভারসাম্য" aria-label="Permalink to &quot;5. মৌলিক সহায়তা ও বেশি পরিশ্রম বেশি পুরস্কারের ভারসাম্য&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কারের মানে এই নয় যে সহজীবী সভ্যতা সম্পূর্ণ &quot;জঙ্গল সমাজ&quot;। বরং, বেশি পরিশ্রম বেশি পুরস্কারকে অবশ্যই &quot;সবার জন্য পথ&quot; মৌলিক সহায়তার সাথে মিলিয়ে চলতে হবে, তখনই ন্যায়বিচার ও দক্ষতার ঐক্য অর্জন করা যায়।</p><p>সহজীবী সভ্যতা &quot;বিবর্তনের মৌলিক সহায়তা রেখা&quot; স্থাপন করেছে, এবং প্রতিটি জীব তার অবদানের পরিমাণ নির্বিশেষে, নিম্নলিখিত মৌলিক সহায়তা পেতে সক্ষম:</p><ul><li>তিনশটি মূল সাধনা পদ্ধতির মৌলিক উপায়ের বিনামূল্যে অর্জনের অধিকার</li><li>সর্বনিম্ন পরিমাণের সাধনা সম্পদ বণ্টন (মৌলিক সাধনা ও বেঁচে থাকা বজায় রাখার জন্য যথেষ্ট)</li><li>মৌলিক চিকিৎসা ও শিক্ষা সেবা</li><li>নোঙর বিন্দু জালের সর্বনিম্ন স্তরের সংযোগ অধিকার</li></ul><p>মৌলিক সহায়তা রেখার উপরে, সম্পদ বণ্টন কঠোরভাবে বেশি পরিশ্রম বেশি পুরস্কার নীতি অনুসরণ করে। এই &quot;নিম্নসীমা সহায়তা + অবদান অনুযায়ী বণ্টন&quot; দ্বিস্তর কাঠামো, দুর্বলদের মৌলিক বিবর্তন অধিকার রক্ষা করে এবং শক্তিশালীদের সৃষ্টি ও অবদানকে উদ্বুদ্ধ করে।</p><h2 id="_6-বেশি-পরিশ্রম-বেশি-পুরস্কারের-বিকৃতি-প্রতিরোধের-ব্যবস্থা" tabindex="-1">6. বেশি পরিশ্রম বেশি পুরস্কারের বিকৃতি প্রতিরোধের ব্যবস্থা <a class="header-anchor" href="#_6-বেশি-পরিশ্রম-বেশি-পুরস্কারের-বিকৃতি-প্রতিরোধের-ব্যবস্থা" aria-label="Permalink to &quot;6. বেশি পরিশ্রম বেশি পুরস্কারের বিকৃতি প্রতিরোধের ব্যবস্থা&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কার বাস্তবে বিকৃতির ঝুঁকির মুখোমুখি হতে পারে, সহজীবী সভ্যতা নিম্নলিখিত প্রতিরোধ ব্যবস্থা স্থাপন করেছে:</p><ul><li><strong>একচেটিয়া বিরোধী ব্যবস্থা</strong>: ব্যক্তি বা গোষ্ঠীর সম্পদ একচেটিয়া করার মাধ্যমে অযৌক্তিক অতিরিক্ত অবদান অর্জন করা নিষিদ্ধ, একচেটিয়া বিরোধী আইনে এ বিষয়ে স্পষ্ট বিধান রয়েছে</li><li><strong>প্রজন্মান্তর ন্যায়বিচার ব্যবস্থা</strong>: অবদান মান সম্পূর্ণরূপে উত্তরাধিকার সূত্রে প্রাপ্ত করা যায় না, &quot;অবদানের বংশগতি&quot; এর ফলে সৃষ্ট শ্রেণি স্থিরতা প্রতিরোধ করা</li><li><strong>অবদানের সত্যতা যাচাই</strong>: নোঙর বিন্দু জাল অবদান ডেটা ক্রস-যাচাই করে, মিথ্যা অবদান প্রতিরোধ করা</li><li><strong>গতিশীল সামঞ্জস্য ব্যবস্থা</strong>: অবদান মূল্যায়নের ওজন ও মানদণ্ড সভ্যতার বিকাশের প্রয়োজন অনুযায়ী নিয়মিত সামঞ্জস্য করা হয়, কোনো এক ধরনের অবদান অত্যধিক প্রসারিত হওয়া প্রতিরোধ করা</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>বেশি পরিশ্রম বেশি পুরস্কার হলো নোঙর সহজীবী সভ্যতার বণ্টন ব্যবস্থার মূল নীতি। এটি লুণ্ঠনবাদের &quot;শক্তিশালী সবকিছু পায়&quot; থেকেও আলাদা, এবং গড়বাদের &quot;গড় খাবার&quot; থেকেও আলাদা; বরং এটি মৌলিক সহায়তার ভিত্তিতে, অবদান অনুযায়ী সম্পদ ও সুযোগ বণ্টন করে, এবং ন্যায়বিচার ও দক্ষতার ঐক্য অর্জন করে। বেশি পরিশ্রম বেশি পুরস্কারের চূড়ান্ত লক্ষ্য হলো প্রতিটি জীবের পরিশ্রমের প্রতিদান থাকা, এবং প্রতিটি জীবের সম্ভাবনাকে সম্পূর্ণরূপে প্রদর্শন করা।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>08-人人有路保障体系 (সবার জন্য পথ সহায়তা ব্যবস্থা)</li><li>22-资源分配联产承包机制 (সম্পদ বণ্টনের উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থা)</li><li>41-共生劳动法 (সহজীবী শ্রম আইন)</li></ul>',37)])])}const b=a(o,[["render",d]]);export{q as __pageData,b as default};
